option.value:
/* ----- CONFIGURACIÓN GENERAL ----- */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

/* Scroll suave para navegación */
html {
    scroll-behavior: smooth;
}

body {
    font-family: Arial, sans-serif;
}

/* ----- HEADER ----- */
.header {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 20px 100px;
    position: relative;
}

/* ----- LOGO ----- */
.logo {
    font-size: 18px;
    font-weight: bold;
}

.logo .tag {
    font-weight: normal;
}

/* ----- NAV ----- */
.nav {
    display: flex;
    gap: 40px;
    transition: all 0.3s ease;
}

/* ----- MENÚ HAMBURGUESA ----- */
.hamburger {
    display: none;
    flex-direction: column;
    cursor: pointer;
    gap: 5px;
    z-index: 1001;
    background: none;
    border: none;
    padding: 5px;
}

.hamburger span {
    width: 25px;
    height: 3px;
    background: black;
    border-radius: 3px;
    transition: all 0.3s ease;
}

.hamburger.active span:nth-child(1) {
    transform: rotate(45deg) translate(8px, 8px);
}

.hamburger.active span:nth-child(2) {
    opacity: 0;
}

.hamburger.active span:nth-child(3) {
    transform: rotate(-45deg) translate(7px, -7px);
}

/* Enlaces del menú: se igualan alturas */
.nav-link {
    text-decoration: none;
    color: black;
    font-size: 14px;
    letter-spacing: 1px;

    /* Ajuste clave para que todos tengan la MISMA altura */
    padding: 8px 10px;
}

/* ----- LINK ACTIVO (ABOUT) ----- */
.nav-link.active {
    background: black;
    color: white;
    border-radius: 8px;
    padding: 8px 18px; /* ancho mayor, pero misma altura */
}

/* ----- DIVISOR INFERIOR negro ----- */
.divider {
    width: 100%;
    height: 4px;
    background: black;
}

.title{
    width: 100%;
    height: auto;
    margin-top: 40px;
    text-align: center;
}

.subtitle{
    margin-top: 30px;
    text-align: center;
    position: relative;
    width: 100%;
    height: auto;
}

/* ----- FOOTER ----- */
.footer {
    background: linear-gradient(135deg, #1a1a1a 0%, #2d2d2d 100%);
    color: white;
    padding: 60px 80px 0;
    border-top: 4px solid black;
    margin-top: 80px;
}

.footer-container {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 1.5fr;
    gap: 50px;
    max-width: 1400px;
    margin: 0 auto;
    padding-bottom: 40px;
}

/* COLUMNA BRAND */
.footer-brand {
    max-width: 350px;
}

.footer-brand h3 {
    font-size: 24px;
    margin-bottom: 15px;
    color: white;
}

.tag-footer {
    color: #4CAF50;
    font-weight: normal;
}

.footer-description {
    color: #b0b0b0;
    font-size: 14px;
    line-height: 1.6;
    margin-bottom: 25px;
}

.social-icons {
    display: flex;
    gap: 15px;
}

.social-icons a {
    width: 40px;
    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(255, 255, 255, 0.1);
    border-radius: 50%;
    color: white;
    text-decoration: none;
    font-size: 18px;
    transition: all 0.3s ease;
}

.social-icons a:hover {
    background: #4CAF50;
    transform: translateY(-3px);
}

/* COLUMNAS DE LINKS */
.footer-column h4 {
    font-size: 18px;
    margin-bottom: 20px;
    color: white;
    font-weight: 600;
}

.footer-column ul {
    list-style: none;
    padding: 0;
}

.footer-column ul li {
    margin-bottom: 12px;
    display: flex;
    align-items: center;
    gap: 10px;
}

.footer-column ul li i {
    color: #4CAF50;
    font-size: 14px;
    width: 16px;
}

.footer-column a,
.footer-column span {
    color: #b0b0b0;
    text-decoration: none;
    font-size: 14px;
    transition: all 0.3s ease;
}

.footer-column a:hover {
    color: white;
    padding-left: 5px;
}

/* FOOTER BOTTOM */
.footer-bottom {
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    padding: 25px 0;
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 15px;
    max-width: 1400px;
    margin: 0 auto;
}

.footer-bottom p {
    color: #888;
    font-size: 14px;
    margin: 0;
}

.footer-bottom-links {
    display: flex;
    align-items: center;
    gap: 15px;
}

.footer-bottom-links a {
    color: #888;
    text-decoration: none;
    font-size: 14px;
    transition: color 0.3s ease;
}

.footer-bottom-links a:hover {
    color: white;
}

.footer-bottom-links span {
    color: #555;
}

/* ----- OVERLAY PARA MENÚ MÓVIL ----- */
.overlay {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100vh;
    background: rgba(0, 0, 0, 0.5);
    z-index: 999;
    opacity: 0;
    transition: opacity 0.3s ease;
}

.overlay.active {
    display: block;
    opacity: 1;
}

/* ----- RESPONSIVIDAD HEADER ----- */
@media (max-width: 900px) {
    .header {
        padding: 20px 60px;
    }

    .hamburger {
        display: flex;
    }

    .nav {
        position: fixed;
        top: 0;
        right: -100%;
        width: 70%;
        max-width: 350px;
        height: 100vh;
        background: white;
        flex-direction: column;
        justify-content: center;
        align-items: center;
        gap: 30px;
        box-shadow: -5px 0 15px rgba(0, 0, 0, 0.2);
        transition: right 0.4s ease;
        z-index: 1000;
    }

    .nav.active {
        right: 0;
    }

    .nav-link {
        font-size: 16px;
        padding: 10px 20px;
    }

    .nav-link.active {
        padding: 10px 25px;
    }
}

@media (max-width: 600px) {
    .header {
        padding: 20px 30px;
    }

    .nav {
        width: 85%;
    }
}

/* ----- RESPONSIVIDAD FOOTER ----- */
@media (max-width: 1100px) {
    .footer-container {
        grid-template-columns: 2fr 1fr 1fr;
        gap: 40px;
    }

    .footer-column:last-child {
        grid-column: 1 / -1;
    }
}

@media (max-width: 768px) {
    .footer {
        padding: 40px 40px 0;
    }

    .footer-container {
        grid-template-columns: 1fr 1fr;
        gap: 35px;
    }

    .footer-brand {
        grid-column: 1 / -1;
        max-width: 100%;
    }

    .footer-bottom {
        flex-direction: column;
        text-align: center;
        padding: 20px 0;
    }
}

@media (max-width: 480px) {
    .footer {
        padding: 30px 20px 0;
    }

    .footer-container {
        grid-template-columns: 1fr;
        gap: 30px;
    }

    .footer-column:last-child {
        grid-column: 1;
    }

    .social-icons {
        justify-content: center;
    }

    .footer-brand {
        text-align: center;
    }

    .footer-column {
        text-align: center;
    }

    .footer-column ul li {
        justify-content: center;
    }
}

